$raiz = "C:\Users\cotaw\Desktop\aw-marcenaria"

$arquivos = @{
    "tailwind.config.js" = ""
    "src\components\sections\Portfolio.jsx" = ""
    "src\components\sections\Faq.jsx" = ""
    "src\components\Footer.jsx" = ""
    "src\components\sections\Contato.jsx" = ""
}

foreach ($rel in $arquivos.Keys) {
    $destino = Join-Path $raiz $rel
    $pastaDestino = Split-Path $destino -Parent
    New-Item -ItemType Directory -Force -Path $pastaDestino | Out-Null
    $bytes = [System.Convert]::FromBase64String($arquivos[$rel])
    [System.IO.File]::WriteAllBytes($destino, $bytes)
    Write-Host "OK - $rel"
}

Write-Host ""
Write-Host "Reescrita completa: tailwind.config.js, Portfolio.jsx, Faq.jsx, Footer.jsx, Contato.jsx"
Write-Host ""
Write-Host "Agora o patch cirurgico do Sobre.jsx (nao tenho o conteudo completo, entao so troco a classe especifica):"

$sobrePath = Join-Path $raiz "src\components\sections\Sobre.jsx"
$conteudoSobre = Get-Content -LiteralPath $sobrePath -Raw

$antigoSobre = '<span className="font-texto text-dourado tracking-[0.3em] text-sm uppercase">'
$novoSobre = '<span className="font-texto text-dourado-escuro tracking-[0.3em] text-sm uppercase">'

if ($conteudoSobre.Contains($antigoSobre)) {
    $conteudoNovoSobre = $conteudoSobre.Replace($antigoSobre, $novoSobre)
    [System.IO.File]::WriteAllText($sobrePath, $conteudoNovoSobre)
    Write-Host "OK - Sobre.jsx (patch cirurgico aplicado)"
} else {
    Write-Host "AVISO - Sobre.jsx nao tem a classe exata esperada. Confira manualmente:"
    Write-Host "  Procure a linha com text-dourado tracking-[0.3em] e troque para text-dourado-escuro"
}
